# Generate the three supplied demos from their repeated tile patterns and marker coordinates.
d1=[[7]*22 for _ in range(19)]
for c in range(22): d1[0][c]=d1[11][c]=2
for r in range(19): d1[r][0]=d1[r][21]=2
for r in (0,11):
    for c in (0,21): d1[r][c]=8

h2,w2=28,27
d2=[[5]*w2 for _ in range(h2)]
for r in [0,5,10,15,20,25]:
    for c in range(w2): d2[r][c]=3
for c in [1,5,9,13,17,21,25]:
    for r in range(h2): d2[r][c]=3
for r in (0,5):
    for c in (13,17,21,25): d2[r][c]=9
for r in (10,15,20):
    for c in (13,17,21,25): d2[r][c]=7
for r in (5,10,15,20):
    for c in (5,9): d2[r][c]=4

h3,w3=29,22
d3=[[2]*w3 for _ in range(h3)]
for r in [2,6,10,14,18,22,26]:
    for c in range(w3): d3[r][c]=5
for c in [0,5,10,15,20]:
    for r in range(h3): d3[r][c]=5
m3={2:[5,10,15,20],6:[5,10,15,20],10:[5,10],14:[5,10,15],18:[5,10,15,20],22:[0,5,10,15,20],26:[0,5,10,15,20]}
for r,cs in m3.items():
    for c in cs: d3[r][c]=4

for name,d in [('demo1',d1),('demo2',d2),('demo3',d3)]:
    print(name, transform(d))
